{
  "title": "迷雾森林的秘密",
  "scene": "你和部落的朋友们来到了一片古老的森林。森林里雾气缭绕，几乎看不清前方。突然，一只名叫虎蛟的异兽出现在你们面前，它看起来既好奇又凶猛。老族长曾说，虎蛟守护着山海经中的一件神器，但只有真正纯净的心灵才能获得它的认可。你的朋友们都很害怕，但你记得族长还提过，虎蛟喜欢听故事。",
  "goal": "获得虎蛟的认可，找到神器。",
  "clue": "族长提到虎蛟喜欢听故事，而不是直接对抗或逃跑。",
  "choices": [
    {
      "id": "A",
      "text": "用部落的盾牌和虎蛟战斗",
      "outcome": "你举着盾牌向前冲去，但虎蛟只是轻巧地躲开，显然并不想和你战斗。它反而显得更加警觉，最终消失在雾中，你没能找到神器。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "尝试绕过虎蛟，悄悄前进",
      "outcome": "你和朋友们小心翼翼地绕过虎蛟，但虎蛟发现了你们的行动，用尾巴一扫，把你们推回了起点。你感到有些失望，但没有受伤。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "给虎蛟讲一个有趣的故事",
      "outcome": "你鼓起勇气，开始给虎蛟讲故事。虎蛟似乎很感兴趣，静静地听着。讲完后，它用鼻子轻触你的手，然后退到一边，露出一条通向神器的道路。你们成功找到了神器。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
